from math import *
def calc(a,b):
    delta = (b-a)/500
    ans = 0
    x = a + delta
    for _ in range(500):
        ans += delta*sin(sqrt(x))/5.68
        x += delta  
    return ans 

t = int(input())
for _ in range(t):
